// n8n runs this workflow whenever a workflow that names it as its error workflow stops on
// an unhandled error. The payload carries the failure context but not the input data that
// caused it, so the alert links back to the execution instead of quoting the row.
//
// The error message is upstream text: an Open Collective or Slack API response, or a Code
// node throw that embeds one. It reaches the reviewers' channel verbatim, so <!channel> or
// a masked link inside it would be honoured by Slack. Escape the three characters Slack
// treats as control characters, & first so the other two are not escaped twice. Same
// treatment as the application messages, for the same reason.
const escapeSlack = (value) => String(value)
  .replace(/&/g, '&amp;')
  .replace(/</g, '&lt;')
  .replace(/>/g, '&gt;');

const channel = $env.SLACK_CHANNEL || '';
if (!channel) throw new Error('failure alert: SLACK_CHANNEL is empty');

// Every field is read defensively. A trigger-level failure produces no lastNodeExecuted,
// and a crash between nodes can leave error empty, so a missing field must drop its line
// rather than put the string "undefined" in front of a reviewer.
return $input.all().map((item) => {
  const execution = item.json.execution || {};
  const workflow = item.json.workflow || {};
  const error = execution.error || {};
  const editorUrl = execution.url ? execution.url.split('/executions/')[0] : '';
  const text = [
    `:rotating_light: *${escapeSlack(workflow.name || 'unknown workflow')}* failed`,
    execution.lastNodeExecuted ? `Failed node: \`${escapeSlack(execution.lastNodeExecuted)}\`` : null,
    error.message ? `Error: ${escapeSlack(error.message)}` : null,
    execution.url ? `Execution: ${execution.url}` : null,
    editorUrl ? `Editor: ${editorUrl}` : null,
  ].filter(Boolean).join('\n');
  return { json: { channel, text } };
});
